def local_file(path):
    import stat
    path=Path(path)
    name=path.relative_to(R).as_posix()
    require(name and '\\' not in name and ':' not in name and all(x not in ['.','..'] for x in Path(name).parts), 'Canonical local saved evidence')
    cursor=R
    for component in Path(name).parts:
        cursor=cursor/component;entry=cursor.lstat()
        require(not stat.S_ISLNK(entry.st_mode) and not getattr(entry,'st_file_attributes',0)&stat.FILE_ATTRIBUTE_REPARSE_POINT, 'No redirected saved evidence')
    return path


